// Des: Tests for M17 bench: list parsing, tally, table text
// Flo: mock site + mock vendor > benchRun over a list > assert per-level hit rate and per-tier cost rows
// I/O: mock server > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const benc = @import("ct-ctrl-benc.zig"); const rigz = @import("te-brow-rig.zig");
const allo = std.testing.allocator;
test "list parser: levels, comments, bad lines" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const got = try benc.listRead(aren.allocator(), "# c\nL1 http://a.test/x\n\nL6 http://b.test/y\n"); try std.testing.expectEqual(@as(usize, 2), got.len); try std.testing.expectEqual(@as(u8, 6), got[1].level); try std.testing.expectError(error.BadUsage, benc.listRead(aren.allocator(), "http://a.test/x")); try std.testing.expectError(error.BadUsage, benc.listRead(aren.allocator(), "L0 http://a.test/x")); try std.testing.expectError(error.BadUsage, benc.listRead(aren.allocator(), "L10 http://a.test/x")); }
test "bench: free pages and vendor pages tallied, failures listed, table written" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); rig.lad.sess = null; var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const a = aren.allocator(); var b1: [64]u8 = undefined; var b2: [64]u8 = undefined; var b3: [64]u8 = undefined; var b4: [64]u8 = undefined; const items = [_]benc.Item{ .{ .level = 1, .urlz = try a.dupe(u8, rig.srv.urlOf(&b1, "/p1")) }, .{ .level = 1, .urlz = try a.dupe(u8, rig.srv.urlOf(&b2, "/p2")) }, .{ .level = 5, .urlz = try a.dupe(u8, rig.srv.urlOf(&b3, "/e403")) }, .{ .level = 6, .urlz = try a.dupe(u8, rig.srv.urlOf(&b4, "/img")) } }; const res = try benc.benchRun(a, &rig.lad, &items); try std.testing.expect(res[0].good and res[1].good and res[2].good); try std.testing.expect(!res[3].good); try std.testing.expectEqual(@as(i64, 1), res[0].tier); try std.testing.expect(res[2].tier >= 2); const txt = try benc.benchText(a, res, "2026-11-21"); try std.testing.expect(std.mem.indexOf(u8, txt, "## Bench 2026-11-21") != null); try std.testing.expect(std.mem.indexOf(u8, txt, "| L1 | 2 | 2 | 100% | 0 |") != null); try std.testing.expect(std.mem.indexOf(u8, txt, "| L6 | 1 | 0 | 0% | 0 |") != null); try std.testing.expect(std.mem.indexOf(u8, txt, "- failed L6:") != null); try std.testing.expect(std.mem.indexOf(u8, txt, "T1 own | 2 |") != null); }
